            variables.Leer(VariableLlaveLlm),
            Valor("LLM_PROVEEDOR"),
            Valor("LLM_URL_BASE"),
            Valor("LLM_MODELO"),
            LeerDecimal(Valor("LLM_PRECIO_ENTRADA")),
            LeerDecimal(Valor("LLM_PRECIO_SALIDA")));
    }

    private static Action<string> AdvertirPor(ILogger logger) =>
