namespace TutorFlow.Core.Asistente;

public sealed class LimitesAsistente
{
    public int MaximoCaracteresPregunta { get; init; } = 1000;
    public int MaximoBytesCuerpo { get; init; } = 16 * 1024;
    public int PreguntasPorMinutoPorIp { get; init; } = 60;
    public int MaximoSeccionesRecuperadas { get; init; } = 6;
    public int MaximoTokensSalida { get; init; } = 2000;
    public int MaximoInvocacionesHerramientas { get; init; } = 4;
    public int TimeoutLlmSegundos { get; init; } = 20;
    public int PresupuestoApiAcademicaSegundos { get; init; } = 6;
    public decimal PresupuestoDiarioUsd { get; init; } = 5m;
    public int MaximoIdentidadesPorIp { get; init; } = 3;
    public int VentanaIdentidadesMinutos { get; init; } = 10;
    public bool BloquearMultiplesIdentidades { get; init; }
}
namespace TutorFlow.Core.Asistente;

public sealed class PresupuestoDiario
{
    private readonly Lock _candado = new();
    private readonly IReloj _reloj;
    private readonly LimitesAsistente _limites;
    private DateOnly _dia;
    private decimal _gastado;
    private decimal _reservado;

    public PresupuestoDiario(IReloj reloj, LimitesAsistente limites)
    {
        _reloj = reloj;
        _limites = limites;
        _dia = DiaActual();
    }

    public bool TryReservar(decimal reservaUsd)
    {
        lock (_candado)
        {
            ReiniciarSiCambioElDia();
            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
            if (_gastado + _reservado + reserva > _limites.PresupuestoDiarioUsd)
            {
                return false;
            }

            _reservado += reserva;
            return true;
        }
    }

    public void Sustituir(decimal reservaUsd, decimal costoRealUsd)
    {
        lock (_candado)
        {
            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
            _reservado = Math.Max(0m, _reservado - reserva);
            ReiniciarSiCambioElDia();
            _gastado += costoRealUsd;
        }
    }

    private DateOnly DiaActual() => DateOnly.FromDateTime(_reloj.AhoraUtc.UtcDateTime);

    private void ReiniciarSiCambioElDia()
    {
        var hoy = DiaActual();
        if (hoy == _dia)
        {
            return;
        }

        _dia = hoy;
        _gastado = 0m;
    }
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed class FaseDelModelo
{
    private const string InicioDeLaInstruccion = "Tu respuesta anterior no se pudo verificar: ";
    private const string FinDeLaInstruccion = ". Responde de nuevo usando solo los datos y las secciones entregados.";

    private readonly IClienteLlm _clienteLlm;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly LimitesAsistente _limites;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly PresupuestoDiario _presupuesto;
    private readonly EmisorDeResultados _emisor;
    private readonly CierreDeRespuesta _cierre;
    private readonly LectorResumenPropio _lectorResumen;

    public FaseDelModelo(
        IClienteLlm clienteLlm,
        PoliticaAcceso politicaAcceso,
        LimitesAsistente limites,
        ConfiguracionAsistente configuracion,
        PresupuestoDiario presupuesto,
        EmisorDeResultados emisor,
        CierreDeRespuesta cierre)
    {
        _clienteLlm = clienteLlm;
        _politicaAcceso = politicaAcceso;
        _limites = limites;
        _configuracion = configuracion;
        _presupuesto = presupuesto;
        _emisor = emisor;
        _cierre = cierre;
        _lectorResumen = new LectorResumenPropio(politicaAcceso);
    }

    public async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken limite, CancellationToken cliente)
    {
        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
        var herramientas = new HerramientasAsistente(sesion.Api, _politicaAcceso);
        var entrada = await PrepararEntradaAsync(sesion, contexto, herramientas, limite);
        var conversacion = new ConversacionLlm(_clienteLlm, herramientas, _limites, sesion.Uso, _configuracion);
        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, limite);
        return resultado.Estado == EstadoConversacion.Completada
            ? await CerrarAsync(new Turno(sesion, contexto, entrada, conversacion, resultado), limite, cliente)
            : Terminal(sesion, resultado);
    }

    private async Task<ResultadoPregunta> CerrarAsync(Turno turno, CancellationToken limite, CancellationToken cliente)
    {
        var primero = _cierre.Evaluar(turno.Sesion, turno.Resultado.Texto ?? string.Empty, turno.Entrada);
        if (primero.MotivoDeReintento is null || !_presupuesto.TryReservar(_configuracion.ReservaPorPeticionUsd))
        {
            return Emitir(turno.Sesion, primero);
        }

        turno.Sesion.ReservasExtra++;
        turno.Sesion.Reintento = true;
        try
        {
            return await ReintentarAsync(turno, primero, limite);
        }
        catch (OperationCanceledException) when (!cliente.IsCancellationRequested)
        {
            return Emitir(turno.Sesion, primero);
        }
    }

    private async Task<ResultadoPregunta> ReintentarAsync(Turno turno, CierreEvaluado primero, CancellationToken limite)
    {
        var instruccion = $"{InicioDeLaInstruccion}{primero.MotivoDeReintento}{FinDeLaInstruccion}";
        var segundo = await turno.Conversacion.ReintentarAsync(turno.Contexto, turno.Entrada.PromptSistema, turno.Resultado, instruccion, turno.Sesion.Registro, limite);
        return segundo.Estado switch
        {
            EstadoConversacion.Completada => Emitir(turno.Sesion, ElegirEntre(primero, _cierre.Evaluar(turno.Sesion, segundo.Texto ?? string.Empty, turno.Entrada))),
            EstadoConversacion.IdAjeno => _emisor.Denegar(turno.Sesion, MotivoDenegacion.HerramientaIdAjeno, turno.Sesion.Uso.Valor.Total, segundo.IdSolicitado),
            _ => Emitir(turno.Sesion, primero)
        };
    }

    private static CierreEvaluado ElegirEntre(CierreEvaluado primero, CierreEvaluado segundo) => segundo.Bloqueado ? primero : segundo;

    private ResultadoPregunta Emitir(SesionPregunta sesion, CierreEvaluado cierre) =>
        _emisor.Responder(sesion, cierre.Texto, cierre.Citas, cierre.Resultado, cierre.UsoDatos);

    private ResultadoPregunta Terminal(SesionPregunta sesion, ResultadoConversacion resultado) => resultado.Estado switch
    {
        EstadoConversacion.IdAjeno => _emisor.Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
        EstadoConversacion.LimiteHerramientas => _emisor.NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
        EstadoConversacion.ContextoTruncado => ResponderContextoTruncado(sesion),
        _ => _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error)
    };

    private ResultadoPregunta ResponderContextoTruncado(SesionPregunta sesion)
    {
        sesion.ContextoTruncado = true;
        return _emisor.Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error);
    }

    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, HerramientasAsistente herramientas, CancellationToken cancellationToken)
    {
        var resumen = await _lectorResumen.LeerAsync(contexto, sesion.Activacion, sesion.Api, sesion.Registro, cancellationToken);
        var prelectura = await PrelecturaAsync(sesion, contexto, herramientas, cancellationToken);
        foreach (var seccion in sesion.Secciones)
        {
            sesion.Registro.AgregarFuente(ConstructorPrompts.ContenidoEntregado(seccion));
        }

        return new EntradaConversacion(sesion.Entrada.Pregunta, sesion.Secciones, resumen, prelectura, ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
    }

    private async Task<string?> PrelecturaAsync(SesionPregunta sesion, ContextoUsuario contexto, HerramientasAsistente herramientas, CancellationToken cancellationToken)
    {
        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
        var palabras = TokenizadorTexto.Valores(sesion.Entrada.Pregunta);
        return ActivadorPrelectura.Activa(contexto, palabras, programas)
            ? await herramientas.LeerProgramaAsync(contexto, sesion.Registro, cancellationToken)
            : null;
    }

    private sealed record Turno(SesionPregunta Sesion, ContextoUsuario Contexto, EntradaConversacion Entrada, ConversacionLlm Conversacion, ResultadoConversacion Resultado);
}
using System.Diagnostics;
using System.Globalization;
using Microsoft.Net.Http.Headers;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api;

public sealed partial class ProcesadorPregunta
{
    private const string TipoDeContenidoJson = "application/json";
    private const string IpDesconocida = "desconocida";
    private const string TituloTipoNoSoportado = "El tipo de contenido de la solicitud no está soportado.";
    private const string TituloSolicitudInvalida = "La solicitud no es válida.";
    private const string TituloCuerpoDemasiadoGrande = "El cuerpo de la solicitud supera el tamaño permitido.";
    private const string TituloDemasiadasSolicitudes = "Se superó el límite de preguntas. Intenta de nuevo más tarde.";
    private const string TituloServicioNoDisponible = "El servicio no está disponible en este momento. Intenta de nuevo.";

    private readonly LimitesAsistente _limites;
    private readonly LimitadorTasaPorIp _limitadorTasa;
    private readonly AuditorPeticiones _auditor;
    private readonly PreguntarAsistente _preguntarAsistente;
    private readonly ILogger<ProcesadorPregunta> _logger;

    public ProcesadorPregunta(
        LimitesAsistente limites,
        LimitadorTasaPorIp limitadorTasa,
        AuditorPeticiones auditor,
        PreguntarAsistente preguntarAsistente,
        ILogger<ProcesadorPregunta> logger)
    {
        _limites = limites;
        _limitadorTasa = limitadorTasa;
        _auditor = auditor;
        _preguntarAsistente = preguntarAsistente;
        _logger = logger;
    }

    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
    {
        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, Stopwatch.StartNew());
        var tasa = _limitadorTasa.Intentar(peticion.Ip);
        return tasa.Permitido
            ? await ProcesarEntradaAsync(contexto, peticion, cancellationToken)
            : await RechazarPorTasaAsync(contexto, peticion, tasa.SegundosParaReintentar, cancellationToken);
    }

    private async Task<IResult> ProcesarEntradaAsync(HttpContext contexto, DatosPeticion peticion, CancellationToken cancellationToken)
    {
        if (!EsJson(contexto.Request.ContentType))
        {
            return RechazarInvalida(peticion, null, StatusCodes.Status415UnsupportedMediaType, TituloTipoNoSoportado);
        }

        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
        if (cuerpo.ExcedeElLimite)
        {
            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
        }

        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
        return solicitud.EsValida
            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
    }

    private async Task<IResult> RechazarPorTasaAsync(HttpContext contexto, DatosPeticion peticion, int segundosParaReintentar, CancellationToken cancellationToken)
    {
        var solicitud = await LeerSolicitudParaAuditoriaAsync(contexto, cancellationToken);
        return Rechazar429(contexto, peticion, solicitud, segundosParaReintentar);
    }

    private async Task<SolicitudValidada?> LeerSolicitudParaAuditoriaAsync(HttpContext contexto, CancellationToken cancellationToken)
    {
        if (!EsJson(contexto.Request.ContentType))
        {
            return null;
        }

        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
        return cuerpo.ExcedeElLimite ? null : ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
    }

    private static bool EsJson(string? tipoDeContenido) =>
        MediaTypeHeaderValue.TryParse(tipoDeContenido, out var tipo)
        && string.Equals(tipo.MediaType.Value, TipoDeContenidoJson, StringComparison.OrdinalIgnoreCase);

    private static string IpDe(HttpContext contexto)
    {
        var direccion = contexto.Connection.RemoteIpAddress;
        if (direccion is null)
        {
            return IpDesconocida;
        }

        return (direccion.IsIPv4MappedToIPv6 ? direccion.MapToIPv4() : direccion).ToString();
    }

    private async Task<IResult> ResponderAsync(HttpContext contexto, DatosPeticion peticion, SolicitudValidada solicitud, CancellationToken cancellationToken)
    {
        var usuario = new Usuario(solicitud.Rol!.Value, solicitud.UsuarioId!);
        return await PreguntarAsync(contexto, peticion, new PreguntaEntrada(solicitud.Pregunta!, usuario), cancellationToken);
    }

    private async Task<IResult> PreguntarAsync(HttpContext contexto, DatosPeticion peticion, PreguntaEntrada entrada, CancellationToken cancellationToken)
    {
        try
        {
            var resultado = await _preguntarAsistente.EjecutarAsync(entrada, peticion.Ip, peticion.CorrelationId, cancellationToken);
            return Mapear(contexto, resultado);
        }
        catch (Exception excepcion) when (EsFalloDeDependencia(excepcion, cancellationToken))
        {
            RegistrarDependenciaCaida(_logger, excepcion.GetType().Name);
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }
    }

    private static bool EsFalloDeDependencia(Exception excepcion, CancellationToken cancellationToken) =>
        excepcion is DependenciaNoDisponibleException or HttpRequestException or TimeoutException
        || (excepcion is OperationCanceledException && !cancellationToken.IsCancellationRequested);

    private static IResult Mapear(HttpContext contexto, ResultadoPregunta resultado)
    {
        if (resultado.Tipo == TipoResultadoPregunta.LimiteIdentidades)
        {
            return Responder429(contexto, resultado.SegundosParaReintentar);
        }

        if (resultado.Respuesta is not { } respuesta)
        {
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }

        var cuerpo = new PreguntaRespuesta(
            respuesta.Respuesta,
            [.. respuesta.Citas.Select(cita => new CitaRespuesta(cita.Documento, cita.Seccion))],
            respuesta.UsoDatosEstudiante,
            respuesta.Tokens,
            respuesta.CostoUsd);
        var estado = resultado.Tipo == TipoResultadoPregunta.Denegada ? StatusCodes.Status403Forbidden : StatusCodes.Status200OK;
        return Results.Json(cuerpo, statusCode: estado);
    }

    private IResult RechazarInvalida(DatosPeticion peticion, string? pregunta, int estado, string titulo)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            null,
            null,
            pregunta,
            ResultadoAuditoria.Invalida,
            peticion.Cronometro.ElapsedMilliseconds));
        return Results.Problem(statusCode: estado, title: titulo);
    }

    private IResult Rechazar429(HttpContext contexto, DatosPeticion peticion, SolicitudValidada? solicitud, int segundosParaReintentar)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            solicitud?.Rol,
            solicitud?.UsuarioId,
            solicitud?.Pregunta,
            ResultadoAuditoria.Denegada,
            peticion.Cronometro.ElapsedMilliseconds));
        return Responder429(contexto, segundosParaReintentar);
    }

    private static IResult Responder429(HttpContext contexto, int segundosParaReintentar)
    {
        contexto.Response.Headers.RetryAfter = segundosParaReintentar.ToString(CultureInfo.InvariantCulture);
        return Results.Problem(statusCode: StatusCodes.Status429TooManyRequests, title: TituloDemasiadasSolicitudes);
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "Una dependencia no respondió ({TipoDeError}).")]
    private static partial void RegistrarDependenciaCaida(ILogger logger, string tipoDeError);

    private sealed record DatosPeticion(string Ip, string CorrelationId, Stopwatch Cronometro);
}
